/**
 * The contract `select.tsx` (native) and `select.web.tsx` (radix) both
 * implement. Its own module because Metro resolves `./select` to
 * `select.web.tsx` on web.
 *
 * Every part shadcn's select exports is here, so a DOM call site written against
 * shadcn's compiles against either half. The types below are the part that means
 * the same on both platforms; the web half widens each to radix's own props
 * (`name`, `required`, `dir`, `position`, `textValue`, a trigger's `size` and
 * every `<button>` attribute), because it installs over a DOM app's shadcn
 * select. The two scroll buttons render nothing on native: a sheet scrolls by
 * touch and has nothing to put one against.
 */
import type { ReactNode } from "react";

export type SelectProps = {
  /** Controlled when passed; otherwise the select holds its own, starting at `defaultValue`. */
  value?: string | undefined;
  defaultValue?: string | undefined;
  onValueChange?: ((value: string) => void) | undefined;
  disabled?: boolean | undefined;
  /**
   * Whether the menu is open, and being told when that changes.
   *
   * Uncontrolled unless `open` is passed, so `onOpenChange` on its own is a caller who wants to
   * *know* rather than to drive — which is the case that asked for this. A list the server owns
   * should be fetched when the menu opens rather than when the screen mounts, and the opening is
   * the one thing only this component knows.
   */
  open?: boolean | undefined;
  onOpenChange?: ((open: boolean) => void) | undefined;
  children: ReactNode;
};

/**
 * The trigger takes the wiring a bound field hands its control.
 *
 * This is the subset that means the same thing on both platforms: React Native takes
 * `id` and the `aria-*` props as cross-platform props. The web half's trigger is radix's,
 * a real `<button>`, and takes every attribute one does plus shadcn's `size`.
 */
export type SelectTriggerProps = {
  id?: string | undefined;
  disabled?: boolean | undefined;
  "aria-labelledby"?: string | undefined;
  "aria-describedby"?: string | undefined;
  "aria-invalid"?: boolean | undefined;
  "aria-required"?: boolean | undefined;
  "aria-label"?: string | undefined;
  className?: string | undefined;
  onBlur?: (() => void) | undefined;
  children: ReactNode;
};

export type SelectValueProps = {
  placeholder?: string | undefined;
  children?: ReactNode;
};

export type SelectContentProps = {
  className?: string | undefined;
  children: ReactNode;
};

export type SelectItemProps = {
  value: string;
  /** Shown, and skipped: it cannot be chosen. */
  disabled?: boolean | undefined;
  className?: string | undefined;
  children: ReactNode;
};

/** `SelectScrollUpButton` and `SelectScrollDownButton`. Web only in effect: see above. */
export type SelectScrollButtonProps = {
  className?: string | undefined;
  children?: ReactNode;
};

export type SelectGroupProps = {
  children: ReactNode;
};

export type SelectLabelProps = {
  className?: string | undefined;
  children: ReactNode;
};

export type SelectSeparatorProps = {
  className?: string | undefined;
};

export const SELECT_TRIGGER_CLASS =
  "border-input bg-background h-10 w-full flex-row items-center justify-between rounded-md border px-3 py-2";
export const SELECT_TRIGGER_TEXT_CLASS = "text-foreground text-sm";
export const SELECT_ITEM_CLASS = "w-full flex-row items-center rounded-sm py-1.5 pl-8 pr-2";
export const SELECT_ITEM_TEXT_CLASS = "text-sm text-popover-foreground";
export const SELECT_LABEL_CLASS = "px-2 py-1.5 text-muted-foreground text-xs";
export const SELECT_SEPARATOR_CLASS = "-mx-1 my-1 h-px bg-border";

/**
 * Copied from `registry/ui/select.web.tsx` by `scripts/rn2web`.
 * Do not edit — edit the source and re-run `npm run compile`.
 *
 * This is level 4 of the plan: the item has a hand-written web half, so nothing was generated. The
 * same passes still ran over it, and for a file already written against the DOM they find nothing
 * to do beyond pointing its sibling imports at the web tree. That is deliberate — running one
 * pipeline over the whole output tree is what guarantees a hand-written half and a compiled one
 * speak the same prop vocabulary, instead of the two drifting where nobody is looking.
 */

/**
 * The web select: radix. `select.tsx` is the native counterpart and
 * `select-base.ts` holds the contract they share.
 *
 * **It is also shadcn's select, part for part and prop for prop.** It installs
 * over a DOM app's `components/ui/select.tsx`, so every part takes radix's own
 * props — `SelectTrigger` every `<button>` attribute and shadcn's `size`,
 * `SelectContent` `position`/`side`/`align`, `SelectItem` `disabled` and
 * `textValue`, the root `defaultValue`, `name` and `required` — and the two
 * scroll buttons are exported and drawn inside the content, as shadcn draws them.
 * `position` defaults to radix's `"item-aligned"`, which is shadcn's default too.
 */

import { Select as SelectPrimitive } from "radix-ui";
import type { ComponentPropsWithRef, ElementType } from "react";
import {
  SELECT_ITEM_CLASS,
  SELECT_ITEM_TEXT_CLASS,
  SELECT_LABEL_CLASS,
  SELECT_SEPARATOR_CLASS,
  SELECT_TRIGGER_CLASS,
  SELECT_TRIGGER_TEXT_CLASS,
} from "@/components/ui/select-base";
import { cn } from "@/lib/utils";
import { Check, ChevronDown, ChevronUp } from "@/components/ui/icons";

// Each part's props are radix's, with `className` re-declared: radix types it `className?: string`,
// which under `exactOptionalPropertyTypes` rejects the `cond ? "x" : undefined` call sites pass.
type Props<T extends ElementType> = Omit<ComponentPropsWithRef<T>, "className"> & {
  className?: string | undefined;
};

type RootProps = ComponentPropsWithRef<typeof SelectPrimitive.Root>;

/**
 * radix's root props, each also taking an explicit `undefined` — the shared contract's spelling,
 * and what a wrapper forwarding its own optional `open` or `value` passes.
 */
type SelectProps = { [K in keyof RootProps]?: RootProps[K] | undefined };

function Select(props: SelectProps) {
  // An explicit `undefined` is dropped rather than passed on: radix reads the presence of `open`
  // and `value` as the switch between controlled and uncontrolled, and a caller forwarding an
  // unset `open` means "not controlled", not "closed".
  const defined = Object.fromEntries(
    Object.entries(props).filter(([, value]) => value !== undefined),
  ) as RootProps;
  return <SelectPrimitive.Root data-slot="select" {...defined} />;
}

function SelectGroup(props: Props<typeof SelectPrimitive.Group>) {
  return <SelectPrimitive.Group data-slot="select-group" {...props} />;
}

function SelectValue(props: Props<typeof SelectPrimitive.Value>) {
  return <SelectPrimitive.Value data-slot="select-value" {...props} />;
}

function SelectTrigger({
  className,
  size = "default",
  children,
  ...props
}: Props<typeof SelectPrimitive.Trigger> & {
  /** shadcn's shorter trigger. Web only. */
  size?: "sm" | "default" | undefined;
}) {
  return (
    <SelectPrimitive.Trigger
      data-slot="select-trigger"
      data-size={size}
      {...props}
      className={cn(
        SELECT_TRIGGER_CLASS,
        SELECT_TRIGGER_TEXT_CLASS,
        "ring-offset-background focus:ring-ring flex focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive data-[placeholder]:text-muted-foreground data-[size=sm]:h-8 [&>span]:line-clamp-1",
        className,
      )}
    >
      {children}
      <SelectPrimitive.Icon asChild>
        <ChevronDown className="h-4 w-4 opacity-50" />
      </SelectPrimitive.Icon>
    </SelectPrimitive.Trigger>
  );
}

function SelectContent({
  className,
  children,
  position = "item-aligned",
  align = "center",
  ...props
}: Props<typeof SelectPrimitive.Content>) {
  return (
    <SelectPrimitive.Portal>
      <SelectPrimitive.Content
        data-slot="select-content"
        position={position}
        align={align}
        {...props}
        className={cn(
          "bg-popover text-popover-foreground data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 relative z-50 max-h-(--radix-select-content-available-height) min-w-[8rem] origin-(--radix-select-content-transform-origin) overflow-x-hidden overflow-y-auto rounded-md border shadow-md",
          position === "popper" &&
            "data-[side=bottom]:translate-y-1 data-[side=left]:-translate-x-1 data-[side=right]:translate-x-1 data-[side=top]:-translate-y-1",
          className,
        )}
      >
        <SelectScrollUpButton />
        <SelectPrimitive.Viewport
          className={cn(
            "p-1",
            position === "popper" &&
              "h-[var(--radix-select-trigger-height)] w-full min-w-[var(--radix-select-trigger-width)] scroll-my-1",
          )}
        >
          {children}
        </SelectPrimitive.Viewport>
        <SelectScrollDownButton />
      </SelectPrimitive.Content>
    </SelectPrimitive.Portal>
  );
}

function SelectItem({ className, children, ...props }: Props<typeof SelectPrimitive.Item>) {
  return (
    <SelectPrimitive.Item
      data-slot="select-item"
      {...props}
      className={cn(
        SELECT_ITEM_CLASS,
        SELECT_ITEM_TEXT_CLASS,
        "focus:bg-accent focus:text-accent-foreground relative flex cursor-default select-none outline-none data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
        className,
      )}
    >
      <span className="absolute left-2 flex h-3.5 w-3.5 items-center justify-center">
        <SelectPrimitive.ItemIndicator>
          <Check className="h-4 w-4" />
        </SelectPrimitive.ItemIndicator>
      </span>
      <SelectPrimitive.ItemText>{children}</SelectPrimitive.ItemText>
    </SelectPrimitive.Item>
  );
}

function SelectLabel({ className, ...props }: Props<typeof SelectPrimitive.Label>) {
  return (
    <SelectPrimitive.Label
      data-slot="select-label"
      {...props}
      className={cn(SELECT_LABEL_CLASS, className)}
    />
  );
}

function SelectSeparator({ className, ...props }: Props<typeof SelectPrimitive.Separator>) {
  return (
    <SelectPrimitive.Separator
      data-slot="select-separator"
      {...props}
      className={cn(SELECT_SEPARATOR_CLASS, "pointer-events-none", className)}
    />
  );
}

function SelectScrollUpButton({
  className,
  ...props
}: Props<typeof SelectPrimitive.ScrollUpButton>) {
  return (
    <SelectPrimitive.ScrollUpButton
      data-slot="select-scroll-up-button"
      {...props}
      className={cn("flex cursor-default items-center justify-center py-1", className)}
    >
      <ChevronUp className="h-4 w-4" />
    </SelectPrimitive.ScrollUpButton>
  );
}

function SelectScrollDownButton({
  className,
  ...props
}: Props<typeof SelectPrimitive.ScrollDownButton>) {
  return (
    <SelectPrimitive.ScrollDownButton
      data-slot="select-scroll-down-button"
      {...props}
      className={cn("flex cursor-default items-center justify-center py-1", className)}
    >
      <ChevronDown className="h-4 w-4" />
    </SelectPrimitive.ScrollDownButton>
  );
}

export {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectScrollDownButton,
  SelectScrollUpButton,
  SelectSeparator,
  SelectTrigger,
  SelectValue,
};
